<script>
(function(){
	var nav = document.getElementById('kervanNav');
	var lastY = window.scrollY;
	window.addEventListener('scroll', function(){
		var y = window.scrollY;
		if (y > lastY && y > 120) {
			nav.classList.add('kervan-nav-hidden');
		} else {
			nav.classList.remove('kervan-nav-hidden');
		}
		if (nav.dataset.transparentEligible === '1') {
			nav.classList.toggle('kervan-nav-transparent', y <= 40);
		}
		lastY = y;

		var waBtn = document.getElementById('kervanWaBtn');
		if (waBtn && y > 60) {
			waBtn.classList.add('kervan-wa-visible');
		}
	}, { passive: true });

	try {
		var favs = JSON.parse(localStorage.getItem('kervanFavs') || '{}');
		var count = Object.keys(favs).length;
		if (count > 0) {
			var wrap = document.getElementById('kervanNavFav');
			document.getElementById('kervanNavFavCount').textContent = count;
			wrap.style.display = 'inline-flex';
		}
	} catch(e) {}
})();
</script>

<style>
.kervan-wa-float{ position:fixed; bottom:22px; right:22px; z-index:60; width:56px; height:56px; border-radius:50%; background:#25D366; display:flex; align-items:center; justify-content:center; box-shadow:0 10px 26px -8px rgba(0,0,0,.4); border:none; cursor:pointer; transition:opacity .25s ease, transform .25s ease; opacity:0; transform:scale(.7); pointer-events:none; }
.kervan-wa-float.kervan-wa-visible{ opacity:1; transform:scale(1); pointer-events:auto; }
.kervan-wa-float:hover{ transform:scale(1.07); }
@media(max-width:640px){ .kervan-wa-float{ width:50px; height:50px; bottom:16px; right:16px; } }
.kervan-wa-menu{ position:fixed; bottom:88px; right:22px; z-index:60; background:var(--cream,#FBF6EC); border-radius:14px; box-shadow:0 16px 34px -12px rgba(27,36,56,.4); padding:10px; display:none; flex-direction:column; gap:4px; min-width:210px; }
.kervan-wa-menu.open{ display:flex; }
